function normalizeRoundActions(){let limit=actionsThisTurn(),saved=state.roundActions,logged=loggedRoundActions(),counts=saved;if(!counts||state.roundActionsEra!==state.era||state.roundActionsRound!==state.round){counts={...logged.counts};if(state.pendingPlayerTurn)counts.player=Math.max(0,counts.player-1);for(const actor of state.roundDone||[])counts[actor]=limit;if(!logged.hasActions)counts[state.turnOwner]=Math.max(0,(state.actionNo||1)-1)}state.roundActions=counts;state.roundActionsEra=state.era;state.roundActionsRound=state.round;for(const actor of ['automa','player'])counts[actor]=Math.min(limit,Math.max(0,Number(counts[actor])||0));if(counts.automa>=limit&&counts.player>=limit){state.roundDone=['automa','player'];state.actionNo=limit;return}if(limit>1){let partial=['automa','player'].filter(actor=>counts[actor]>0&&counts[actor]<limit);if(partial.length===1)state.turnOwner=partial[0];else if(partial.length===2&&['automa','player'].includes(state.roundStarter))state.turnOwner=state.roundStarter}if(counts[state.turnOwner]>=limit&&counts[state.turnOwner==='automa'?'player':'automa']<limit)state.turnOwner=state.turnOwner==='automa'?'player':'automa';state.actionNo=Math.min(limit,counts[state.turnOwner]+1);state.roundDone=['automa','player'].filter(actor=>counts[actor]>=limit)}
function emptyIndustrySpaces(actor){let removed=actor==='player'?state.playerRemoved:state.removed;return Object.values(GROUPS).flat().filter(group=>group.ids.every(id=>removed?.[id]==='built'||removed?.[id]==='developed')).length}
function heavyTrainsBuilt(actor){return Object.entries(state.edges||{}).filter(([id,e])=>id.startsWith('rail:')&&e.owner===actor&&e.tile!=='light').length}
