  let g=group(s.groupId),id=g?.ids?.find(x=>s.owner==='player'?state.playerRemoved?.[x]==='built':state.removed?.[x]==='built')||g?.ids?.[0],tile=id&&INDUSTRIES[id.split(':')[0]]?.tiles[Number(id.split(':')[1])],points=Number(tile?.[4]||0);
  if(s.industryScoreAwarded===undefined&&(s.owner==='automa'||['k2','k3','k4','m1','m4','m5','m6'].includes(s.groupId))){s.industryScoreAwarded=true;continue}
