function scoreNetworkForEra(label){let linkPoints=city=>(BASE_LINK[city]||0)+(state.cities[city]||[]).reduce((total,s)=>total+(s.owner&&s.owner!=='none'?Number(group(s.groupId)?.effect.match(/링크\s*(\d+)/)?.[1]||0):0),0),earned={automa:0,player:0};for(const [id,e] of Object.entries(state.edges)){if(!id.startsWith('rail:')||!['automa','player'].includes(e.owner))continue;let [a,b]=id.slice(5).split('|');earned[e.owner]+=(linkPoints(a)+linkPoints(b))*(e.networkId==='train-double'?2:1)}for(const actor of ['automa','player'])gainVP(actor,earned[actor]);state.eraScores??={};state.eraScores[state.era]??={};state.eraScores[state.era].network={...earned};log(label+' 링크 점수','오토마 +'+earned.automa+'VP · 플레이어 +'+earned.player+'VP')}
