 let excluded=[],set=yield* automaCandidateSteps(excluded),plan=selectAutomaPlan(true,set);if(plan.switched||plan.previousPlanId!==plan.id)set=yield* automaCandidateSteps(excluded);let goal=selectAutomaGoal(plan,set),opts=evaluateAutomaCandidates(set.opts.filter(o=>!state.rejected.includes((o.type||'')+(o.city||'')+(o.track||'')+(o.networkId||'')+(o.type==='판매'?JSON.stringify(o.sales)+':'+o.whiskey:''))),goal,plan);yield null;if(lookahead)opts=yield* automaLookaheadSteps(opts);
