  let down=Number(quality.match(/수입 −(\d+)/)?.[1]||0);if(down&&!canLoseIncome('automa',down))return false;
  state.qualityClaimed.automa.push(key);
  let cash=Number(quality.match(/\$(\d+)/)?.[1]||0),extra=Number(quality.match(/\+(\d+)VP/)?.[1]||0),spaces=Number(quality.match(/수입 \+(\d+)/)?.[1]||0);
