function latestConstructionIndustryMarkup(logEntry){let title=String(logEntry.title||''),assetName=title.includes('오일 시티')?'oil-rig':title.includes('마천루')?'skyscraper':title.includes('자동차')?'automobile':title.includes('등유')?'kerosene':title.includes('코크스')?'coke-plant':title.includes('제철소')?'steelworks':title.includes('탄광')||title.includes('석탄')?'coal':title.includes('제조 상자')?'manufacturing-crate':'';return assetName?`<img class="recent-industry-icon" src="${actionResourceAsset(assetName)}" alt="">`:''}
function latestNetworkRoutes(logEntry){let cities=Object.keys(NODES).sort((a,b)=>b.length-a.length).map(city=>city.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),found=[],match,pattern=new RegExp(`(${cities})\\s*[—-]\\s*(${cities})`,'g'),text=[logEntry.title,logEntry.detail].join(' · ');while((match=pattern.exec(text))&&found.length<2){let route=match[1]+'—'+match[2];if(!found.includes(route))found.push(route)}return found}
function latestActionMarkup(logEntry){let action=actionKey(logEntry.title),place=action==='build'?latestBuildPlace(logEntry):'',industry=action==='build'?latestConstructionIndustryMarkup(logEntry):'',routes=action==='network'?latestNetworkRoutes(logEntry):[],label=(/^플레이어/.test(logEntry.title||'')?'플레이어':'오토마')+' '+({build:'건설',network:'네트워크',sell:'판매',develop:'개발',loan:'대출',pass:'패스',other:'처리'}[action])+(place?' · '+place:'')+(routes.length?' · '+routes.join(', '):'');let icons=action==='network'?`<span class="recent-network-icons" aria-hidden="true">${routes.length?routes.map(()=>actionIconMarkup(action)).join(''):actionIconMarkup(action)}</span>`:actionIconMarkup(action);return `<button type="button" class="recent-action ${action==='network'?'recent-network-action':''}" data-log-turn="${logEntry.turn}" aria-label="${escapeAuditHtml(label)} 상세 기록 보기">${latestActorMarkup(logEntry)}<span class="recent-plus" aria-hidden="true">+</span>${icons}${industry}${place?`<span class="recent-place">${escapeAuditHtml(place)}</span>`:''}${routes.length?`<span class="recent-routes">${escapeAuditHtml(routes.join(' · '))}</span>`:''}<span class="recent-detail-arrow" aria-hidden="true">›</span></button>`}
function openLogEntry(turn){nav('logView');requestAnimationFrame(()=>$$('.log').find(entry=>entry.dataset.logTurn===String(turn))?.scrollIntoView({block:'center',behavior:'smooth'}))}
function renderLatestLogs(){let latest=(state.logs||[]).filter(l=>actionKey(l.title)!=='other').slice(0,2);$('#latest').innerHTML=latest.length?latest.map(latestActionMarkup).join(''):'아직 처리한 행동이 없습니다.';$$('#latest [data-log-turn]').forEach(button=>button.onclick=()=>openLogEntry(button.dataset.logTurn))}
function renderLogs(){if($('#logView').classList.contains('active'))$('#logs').innerHTML=state.logs.length?state.logs.map(l=>{let settlement=l.title==='라운드 종료'||l.title.endsWith('라운드 수입'),meta=l.era&&l.round?`시대 ${l.era===1?'I':'II'} · 라운드 ${l.round}${settlement?'':` · 행동 ${l.actionNo||1}/${l.era===1&&l.round===1?1:2}`}`:'';return `<article class="log" data-log-turn="${l.turn}"><em>#${l.turn}</em><div><strong>${l.title}</strong>${meta?`<small class="log-round">${meta}</small>`:''}<p>${l.detail}</p>${l.audit?`<details class="decision-audit"><summary>오토마 후보·탈락 사유 보기</summary><pre>${escapeAuditHtml(l.audit)}</pre></details>`:''}<small>${l.time}</small></div></article>`}).join(''):'<p class="muted">아직 기록이 없습니다.</p>';renderLatestLogs()}
function plainLogText(){return [...state.logs].reverse().map(l=>['#'+l.turn+' · 시대 '+(l.era===1?'I':'II')+' · 라운드 '+l.round+' · 행동 '+(l.actionNo||1)+' · '+l.title,l.detail,l.audit?'[오토마 판단 기록]\n'+l.audit:''].filter(Boolean).join('\n')).join('\n\n')}
function renderFinalScore(){let box=$('#finalScore');if(!box)return;box.hidden=!state.gameOver;if(!state.gameOver)return;let scores=state.gameOver.scores||finalScoreBreakdown();scores=Object.fromEntries(['player','automa'].map(actor=>[actor,{...scores[actor],sewing:scores[actor].sewing||[eraScore(1).sewing[actor],eraScore(2).sewing[actor]],adjustments:Number(scores[actor].adjustments||0)}]));let rows=[['네트워크 · 시대 I',s=>s.network[0]],['네트워크 · 시대 II',s=>s.network[1]],['네트워크 합계',s=>s.network[0]+s.network[1]],['산업 · 시대 I',s=>s.industry[0]],['산업 · 시대 II',s=>s.industry[1]],['산업 합계',s=>s.industry[0]+s.industry[1]],['재봉틀 · 시대 I/II',s=>s.sewing[0]+' / '+s.sewing[1]],['다상 교류 발전기 · 시대 I/II',s=>s.polyphase[0]+' / '+s.polyphase[1]],['기관차 공장 · 중량열차',s=>s.heavyTrains+'개 × 4 = '+s.locomotive],['기타 승점',s=>s.other],['점수 조정',s=>s.adjustments],['최종 승점',s=>s.total]];box.innerHTML='<div class="section-head"><div><p class="eyebrow">게임 종료 정산</p><h2>최종 점수 상세</h2></div></div><div class="final-score-grid"><span>항목</span><b>플레이어</b><b>오토마</b>'+rows.map(([label,value])=>'<span>'+label+'</span><strong>'+value(scores.player)+'</strong><strong>'+value(scores.automa)+'</strong>').join('')+'</div><p class="muted">재봉틀·다상 교류 발전기·기관차 공장은 산업 점수에 포함됩니다. 기타 승점은 판매·보너스이며, 음수 잔차는 점수 조정으로 분리합니다.</p><p>'+escapeAuditHtml(gameResultText())+'</p>'}
async function copyAllLogs(){let button=$('#copyLogBtn'),content=plainLogText();if(!content)return alert('복사할 기록이 없습니다.');try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(content);else{let input=document.createElement('textarea');input.value=content;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();if(!document.execCommand('copy'))throw Error('copy failed');input.remove()}button.textContent='복사 완료';setTimeout(()=>button.textContent='전체 기록 복사',2500)}catch{alert('복사하지 못했습니다. 브라우저의 클립보드 권한을 확인해 주세요.')}}
function renderAll(){refreshGameResult();normalizeRoundActions();if(recoverCompletedRound())normalizeRoundActions();resetPlayerTurnInteraction(false);renderStatus();renderIconStatus();renderTurnOrder();renderRoundTransition();renderProposal();renderFinalScore();if(state.gameOver){let w=state.gameOver.winner;$('#turnBanner').innerHTML='<b>게임 종료 · '+(w==='tie'?'공동 승리':w==='player'?'플레이어 승리':'오토마 승리')+'</b><span>플레이어 '+state.playerVP+'VP · 오토마 '+state.vp+'VP</span>';$('#decideBtn').hidden=true;$('#executeBtn').hidden=true;$('#impossibleBtn').hidden=true;$('#playerPanel').hidden=true;$$('[data-player]').forEach(b=>b.disabled=true);$('#proposalTag').textContent='최종 결과';$('#proposalTitle').textContent=w==='tie'?'공동 승리':w==='player'?'플레이어 승리':'오토마 승리';$('#proposalReason').textContent='플레이어 '+state.playerVP+'VP · 오토마 '+state.vp+'VP'}else if(state.turnOwner==='player'){$('#decideBtn').hidden=true;$('#executeBtn').hidden=true;$('#impossibleBtn').hidden=true;$('#proposalTag').textContent='플레이어 입력';$('#proposalType').textContent='플레이어 차례';$('#proposalTitle').textContent='아래에서 수행할 행동을 선택하세요';$('#proposalReason').textContent='카드와 대상을 고르면 비용·지도·개인판·다음 차례가 한 번에 반영됩니다.'}renderMap();renderMarkets();renderBoard();renderAvailableNow();renderSetup();renderLogs()}
function openOilNode(field){let city=state.oilCities?.[field];if(!mapEditMode){let tile=state.setup?.oil?.[field],owner=city?.owner==='player'?'플레이어':'오토마';return showMapInfo(field,`<p><b>유전 타일</b> ${tile?.revealed?tile.value:'뒷면 · 최초 송유관 연결 시 공개'}</p><p><b>${city?'오일 시티 오일':'공유 오일'}</b> ${oilFieldStock(field)}개</p>${city?`<p><b>오일 시티 V</b> ${owner} · ${city.flipped?'뒤집힘 ($25 지급 완료)':'마지막 오일 소비 시 $25 · 5VP'}</p>`:''}`)}let value=prompt(field+'의 '+(city?'오일 시티':'공유')+' 오일 수',oilFieldStock(field));if(value===null||!Number.isInteger(Number(value))||Number(value)<0)return;snapshot();if(city){city.resource=Number(value);city.resources={오일:city.resource};if(city.resource===0&&!city.flipped){city.flipped=true;city.industryScoreAwarded=false;if(city.owner==='player')state.playerMoney+=25;else state.money+=25;log('오일 시티 수동 소진',field+' · '+(city.owner==='player'?'플레이어':'오토마')+' +$25')}else log('오일 시티 오일 수정',field+' → '+city.resource+'개')}else{state.oilfields[field]=Number(value);log('공유 오일 수정',field+' → '+state.oilfields[field]+'개')}save()}
function openNode(n){if(!mapEditMode){let rows=SLOT_RULES[n]?Array.from({length:citySlots(n)},(_,i)=>{let s=slot(n,i),allowed=slotRules(n)[i]||[],resources=slotResourceEntries(s).map(([r,q])=>r+' '+q+'개').join(' · ');return `<div class="info-slot"><b>${i+1}번 · ${allowed.join('/')}</b><span>${s.owner==='none'?'빈 슬롯':(s.owner==='player'?'플레이어':'오토마')+' · '+(s.industry==='석탄'?'탄광':s.industry)+(resources?' · '+resources:'')+(s.flipped?' · 뒤집힘':'')}</span></div>`}).join(''):'',oil=isOilField(n)?`<p><b>유전 타일</b> ${state.setup?.oil?.[n]?.revealed?state.setup.oil[n].value:'뒷면 · 최초 송유관 연결 시 공개'}</p><p><b>공유 오일</b> ${state.oilfields[n]||0}개</p>`:'',link=BASE_LINK[n]?`<p><b>기본 링크 점수</b> ${BASE_LINK[n]}점</p>`:'',market=MARKET_DEF[n]?`<p><b>고정 자원 시장</b> ${MARKET_DEF[n].type} · 개당 $${MARKET_DEF[n].price}</p>`:'',merchantValue=state.setup?.merchant?.[n]||'',merchant=merchantValue?`<p><b>상인 시장</b> ${state.merchantUsed?.[n]?merchantValue.split(' · ')[0]+' · 최초 판매 보너스 소진':merchantValue+' · 사용 가능'}</p>`:'';return showMapInfo(n,link+market+merchant+oil+rows)}if(isOilField(n)){let v=prompt(n+'의 공유 오일 수',state.oilfields[n]||0);if(v!==null&&!Number.isNaN(+v)){snapshot();state.oilfields[n]=Math.max(0,+v);log('공유 오일 수정',n+' → '+state.oilfields[n]+'개');save()}return}if(!SLOT_RULES[n])return alert(n+'에는 수정할 산업 슬롯이 없습니다.');activeNode=n;$('#nodeTitle').textContent=n;$('#slotInput').innerHTML=Array.from({length:citySlots(n)},(_,i)=>`<option value="${i}">${i+1}번 칸 · ${(slotRules(n)[i]||[]).join('/')}</option>`).join('');$('#industryInput').innerHTML=['',...NODES[n][2],...'석탄,탄광,코크스 공장,제철소,등유,제조 상자,자동차,마천루'.split(',')].filter((x,i,a)=>a.indexOf(x)===i).map(x=>`<option>${x||'선택 안 함'}</option>`).join('');loadSlot();$('#nodeDialog').showModal()}
function loadSlot(){let s=slot(activeNode,+$('#slotInput').value);$('#ownerInput').value=s.owner;$('#industryInput').value=s.industry;$('#levelInput').value=s.level;$('#resourceInput').value=s.resource;$('#flippedInput').checked=s.flipped}
function openTile(groupId){let g=group(groupId),id=g?.ids.find(x=>!state.removed[x]);if(!g||!id||!groupUnlocked(groupId))return;$('#tileTitle').textContent=g.name+' ×'+(g.count-groupUsed(groupId));$('#tileDesc').textContent='건설: '+g.cost+' · 효과: '+g.effect;$('#tileBuild').onclick=()=>manualTile(groupId,id,'built');$('#tileDevelop').onclick=()=>manualTile(groupId,id,'developed');$('#tileDialog').showModal()}
function manualTile(groupId,id,how){snapshot();state.removed[id]=how;let unlocked=NETWORKS.filter(n=>n.req===groupId&&completeGroup(groupId)).map(n=>n.name);log('개인판 · '+group(groupId).name,(how==='built'?'건설':'개발')+(unlocked.length?' · '+unlocked.join(', ')+' 해금':''));$('#tileDialog').close();state.current=null;save()}
function pickerOptionMarkup(x,i,show){let v=String(show(x)),parts=v.split(' · '),network=x&&x.n,src=network?personalNetworkAsset(network.id,'player'):'',special=x.vanderbilt?' vanderbilt-option':'',networkClass=network?' picker-network-option':'',art=src?'<span class="picker-network-art" aria-hidden="true"><img src="'+src+'" alt=""></span>':'',copy='<span class="picker-option-copy"><strong>'+parts.shift()+'</strong>'+(parts.length?'<small>'+parts.join(' · ')+'</small>':'')+(x.vanderbilt?'<em>밴더빌트 구매</em>':'')+'</span>';return '<button type="button" class="picker-option'+networkClass+special+'" data-pick="'+i+'">'+art+copy+'</button>'}
function pick(label,items,show=x=>x,hint='항목을 선택하세요.',vanderbiltItems=[],initialIncludeV=false){return new Promise((resolve,reject)=>{let d=$('#pickerDialog'),box=$('#pickerItems'),done=false,epoch=actionEpoch,includeV=initialIncludeV&&vanderbiltItems.length>0;$('#pickerTitle').textContent=label;$('#pickerHint').textContent=hint;let draw=()=>{let shown=includeV?[...items,...vanderbiltItems]:items;box.innerHTML=(vanderbiltItems.length?'<label class="vanderbilt-toggle"><input type="checkbox" '+(includeV?'checked':'')+'> 밴더빌트 구매 후보 포함</label>':'')+(shown.length?shown.map((x,i)=>pickerOptionMarkup(x,i,show)).join(''):'<p class="picker-empty">기본 자원으로 가능한 대상이 없습니다.</p>');let toggle=box.querySelector('.vanderbilt-toggle input');if(toggle)toggle.onchange=()=>{includeV=toggle.checked;draw()};box.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>finish(shown[+b.dataset.pick]))};let finish=v=>{if(done)return;done=true;if(pendingChoiceAbort===abort)pendingChoiceAbort=null;d.close();requestAnimationFrame(()=>setTimeout(()=>epoch===actionEpoch?resolve(v):reject(new Error('PLAYER_ACTION_CANCELLED')),0))},abort=()=>{if(done)return;done=true;if(pendingChoiceAbort===abort)pendingChoiceAbort=null;if(d.open)d.close();reject(new Error('PLAYER_ACTION_CANCELLED'))};pendingChoiceAbort=abort;draw();d.oncancel=e=>{e.preventDefault();finish(null)};$('#pickerClose').onclick=e=>{e.preventDefault();finish(null)};try{d.showModal()}catch(err){console.error(err);done=true;if(pendingChoiceAbort===abort)pendingChoiceAbort=null;resolve(null);alert('선택 창을 열지 못했습니다. 다시 시도해 주세요.')}})}
function playerConfirmLine(line){let resource=line.match(/^(?:(.+?) 판매 · )?(철|석탄|강철|코크스|오일) ← (.+)$/);if(resource)return `<div class="confirm-resource-row"><img src="${resourceIconPath(resource[2])}" alt=""><b>${resource[1]?escapeAuditHtml(resource[1])+' · ':''}${resource[2]} 1</b><span>${escapeAuditHtml(resource[3])}</span></div>`;let symbol=line.includes('비용')?'$':line.includes('카드')?'▣':line.includes('품질')?'★':line.includes('경로')?'━':'•';return `<p class="confirm-fact"><b aria-hidden="true">${symbol}</b><span>${escapeAuditHtml(line)}</span></p>`}
function confirmAction(title,lines){setPlayerStep('review');if(state.gameMode==='full'){setPlayerStep('apply');return Promise.resolve(true)}return new Promise((resolve,reject)=>{let d=$('#confirmActionDialog'),done=false;$('#confirmActionTitle').textContent=title;$('#confirmActionDetail').innerHTML=lines.map(playerConfirmLine).join('');let finish=v=>{if(done)return;done=true;if(v)setPlayerStep('apply');if(pendingChoiceAbort===abort)pendingChoiceAbort=null;d.close();resolve(v)},abort=()=>{if(done)return;done=true;if(pendingChoiceAbort===abort)pendingChoiceAbort=null;if(d.open)d.close();reject(new Error('PLAYER_ACTION_CANCELLED'))};pendingChoiceAbort=abort;$('#confirmActionApply').onclick=()=>finish(true);$('#confirmActionCancel').onclick=()=>finish(false);$('#confirmActionClose').onclick=e=>{e.preventDefault();finish(false)};d.oncancel=e=>{e.preventDefault();finish(false)};d.showModal()})}
function cardRemaining(card){let limit=CARDS.filter(c=>c===card).length,used=[...(state.discard||[]),...(state.playerDiscard||[])].filter(c=>c===card).length;return Math.max(0,limit-used)}
function physicalAvailableCards(){let counts=new Map(initialPlayerCardCounts(state.seed));for(const card of state.playerDiscard||[])counts.set(card,Math.max(0,(counts.get(card)||0)-1));return [...counts].filter(([,left])=>left>0).map(([card,left])=>({card,left}))}
async function playerCard(){if(tracksPlayerHand())return pick('버릴 카드',state.playerHand||[],x=>x,'현재 손패에서 1장을 선택합니다.');let cards=physicalAvailableCards(),choice=await pick('버릴 카드',cards,x=>x.card+' · 게임에 남은 '+x.left+'장','실제 손패는 비공개입니다. 사용한 카드만 기록하세요.');if(!choice){if(!cards.length)alert('게임에 남은 카드가 없습니다. 버림 기록을 확인해 주세요.');return null}return choice.card}
function playerGroupCandidates(){return Object.entries(GROUPS).flatMap(([track,gs])=>gs.filter(g=>playerGroupUnlocked(g.id)&&playerGroupUsed(g.id)<g.count).map(g=>({track,g})))}
function playerDevelopCandidates(){return playerGroupCandidates().flatMap(({track,g})=>g.ids.filter(id=>!state.playerRemoved[id]).map(id=>({track,g,id})))}
function playerDevelopCandidatesAfter(id){let previous=state.playerRemoved[id];state.playerRemoved[id]='developed';try{return playerDevelopCandidates()}finally{if(previous===undefined)delete state.playerRemoved[id];else state.playerRemoved[id]=previous}}
function playerDevelopTileLabel(choice){return choice.g.name+' · '+(choice.g.ids.indexOf(choice.id)+1)+'번 타일'}
function industryCardNetworkCities(actor){let cities=new Set;for(const [city,slots] of Object.entries(state.cities))if(slots.some(s=>s?.owner===actor))cities.add(city);for(const [id,edge] of Object.entries(state.edges))if(edge?.owner===actor&&/^(rail|pipe):/.test(id))for(const city of id.slice(id.indexOf(':')+1).split('|'))cities.add(city);return cities}
function playerPlan(tile,city,allowVanderbilt=false){return actorPlan(tile,city,'player',allowVanderbilt)}
function planLabel(plan){let v=plan.sources.filter(x=>x.kind==='vanderbilt').reduce((s,x)=>s+x.price,0);return '총 $'+plan.total+(v?' · 밴더빌트 +$'+v:'')}
function chargePlayerSources(tile,city,allowVanderbilt=false){let detail=[],cost=tile[1];state.playerMoney-=tile[1];state.playerSpent+=tile[1];for(const [r,q] of Object.entries(tile[2]))for(const s of sourcePlan(r,q,city,'player',{allowVanderbilt})){if(s.kind==='market'||s.kind==='vanderbilt'){state.playerMoney-=s.price;state.playerSpent+=s.price;cost+=s.price}detail.push(r+' ← '+playerSourceText(s)+applyOilReward(s));flipUsedIndustrySource(s,detail,'player')}return {cost,detail}}
function sellProducedActor(city,res,qty,actor){let connected=connectedFrom(city);connected.add(city);let ms=[...connected].filter(n=>MARKET_DEF[n]?.res.includes(res)&&state.markets[n][res]<2).sort((a,b)=>MARKET_DEF[b].price-MARKET_DEF[a].price),sold=[];for(const n of ms)while(qty&&state.markets[n][res]<2){state.markets[n][res]++;qty--;let cash=MARKET_DEF[n].price;if(actor==='player')state.playerMoney+=cash;else state.money+=cash;if(res==='코크스')gainVP(actor,4);sold.push(n+' $'+cash+(res==='코크스'?' +4VP':''))}return {left:qty,sold}}
function finishPlayer(card,title,detail,metadata={}){state.playerDiscard.push(card);if(tracksPlayerHand()){let i=state.playerHand.indexOf(card);if(i>=0)state.playerHand.splice(i,1)}log('플레이어 · '+title,'폐기 '+card+' · '+detail,metadata);state.turn++;state.pendingPlayerTurn=tracksPlayerHand();if(!state.pendingPlayerTurn)advanceAction('player');state.current=null;save()}
function confirmPlayerTurn(){if(!tracksPlayerHand()||!state.pendingPlayerTurn||playerActionPending||state.turnOwner!=='player')return false;normalizeRoundActions();state.pendingPlayerTurn=false;const advanced=advanceAction('player');save();return advanced}
