function playerNetworkInventory(){return NETWORKS.filter(n=>n.start||withPlayerBoard(()=>completeGroup(n.req))).filter(n=>n.repeatable?(state.lightTrains.player||0)<n.max:!state.playerNetworkBuilt.includes(n.id))}
function playerNetworkOriginCities(){let cities=new Set;for(const [id,e] of Object.entries(state.edges))if(e.owner==='player')id.slice(id.indexOf(':')+1).split('|').forEach(city=>cities.add(city));for(const [city,slots] of Object.entries(state.cities))if(slots.some(slot=>slot.owner==='player'))cities.add(city);return cities}
