function printedStars(groupId){return {k3:1,k4:2,m1:1,m4:1,m5:3,m6:1}[groupId]||0}
function consumeExactPlayerSource(source){if(source.kind==='industry'){let tile=state.cities[source.node]?.[source.index],typed=tile?.resources&&source.resource in tile.resources;if(!tile||(typed?tile.resources[source.resource]:tile.resource)<1)return false;if(typed){tile.resources[source.resource]--;tile.resource=Math.max(0,(Number(tile.resource)||0)-1)}else tile.resource--;return true}if(source.kind==='bonus'){let edge=state.edges[source.edge];if(!edge||(edge.bonusRemaining||0)<1)return false;edge.bonusRemaining--;return true}if(source.kind==='market'){let market=state.markets[source.node];if(!market||(market[source.resource]||0)<1)return false;market[source.resource]--;return true}if(source.kind==='oil'){let city=state.oilCities?.[source.field];if(city){if((city.resource||0)<1)return false;city.resource--;city.resources={오일:city.resource};source.oilCityLast=!city.flipped&&city.resource===0}else{if((state.oilfields[source.field]||0)<1)return false;state.oilfields[source.field]--}return true}return source.kind==='vanderbilt'}
function qualityIncomeDown(stars){let key=stars+'★',reward=state.setup.quality[key];return !reward||qualityClaimedByAnyone(key)?0:Number(reward.match(/수입 −(\d+)/)?.[1]||0)}
