if(state.era===1&&state.round>8){snapshot();normalizeRoundActions();let oldRound=state.round,counts={...state.roundActions};endEraOne();state.era=2;state.round=oldRound-8;beginEraTwoCards(counts);state.roundActionsEra=2;state.roundActionsRound=state.round;log('시대 전환 복구','잘못 표시된 1시대 '+oldRound+'라운드를 2시대 '+state.round+'라운드로 바로잡았습니다. 라운드 수입은 다시 지급하지 않았습니다.');roundTransition={endedEra:1,endedRound:8,nextEra:2,nextRound:state.round,starter:state.roundStarter};roundTransitionTimer=setTimeout(()=>{roundTransition=null;renderRoundTransition()},4000)}
if(state.era===2&&state.round>8&&!state.gameOver){snapshot();let oldRound=state.round;state.round=8;finishGame();log('게임 종료 복구','잘못 표시된 2시대 '+oldRound+'라운드를 게임 종료로 바로잡았습니다. 라운드 수입은 다시 지급하지 않았습니다.');roundTransition={endedEra:2,endedRound:8,gameOver:true};roundTransitionTimer=setTimeout(()=>{roundTransition=null;renderRoundTransition()},8000)}
